import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Pieza } from '../../piezas/entities/pieza.entity';
import { Restaurador } from '../../restauradores/entities/restaurador.entity';

@Injectable()
export class AsignarRestauradorRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Pieza) private readonly piezas: Repository<Pieza>,
    @InjectRepository(Restaurador) private readonly restauradores: Repository<Restaurador>
  ) {}

  buscarPiezaRepository(piezaId: number) {
    return this.piezas.findOneBy({ id: piezaId });
  }

  buscarRestauradorRepository(restauradorId: number) {
    return this.restauradores.findOneBy({ id: restauradorId });
  }

  async asignarRestauradorRepository(piezaId: number, restauradorId: number, rol: string) {
    const asignacion = { piezaId, restauradorId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarRestauradorRepository } from './repository';

@Injectable()
export class AsignarRestauradorService {
  constructor(private readonly repository: AsignarRestauradorRepository) {}

  async asignarRestauradorService(piezaId: number, restauradorId: number, rol: string) {
    const pieza = await this.repository.buscarPiezaRepository(piezaId);
    const restaurador = await this.repository.buscarRestauradorRepository(restauradorId);
    if (!pieza || !restaurador) {
      throw new NotFoundException('No existe la pieza o el restaurador');
    }

    try {
      return await this.repository.asignarRestauradorRepository(piezaId, restauradorId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El restaurador ya está asignado a esa pieza');
      }
      throw error;
    }
  }
}

import { Body, Controller, Param, Post } from '@nestjs/common';
import { AsignarRestauradorService } from './service';

@Controller('piezas/:piezaId/asignaciones')
export class AsignarRestauradorController {
  constructor(private readonly service: AsignarRestauradorService) {}

  @Post()
  asignar(@Param('piezaId') piezaId: string, @Body() datos: { restauradorId: number; rol: string }) {
    return this.service.asignarRestauradorService(Number(piezaId), datos.restauradorId, datos.rol);
  }
}
